parameters.jsCode:
const items = $input.all();
const variables = $('Webhook Type and Variables').item.json.body.variables || {};
const templateType = $('Webhook Type and Variables').item.json.body.templateType || 'NDA';
let templateContent = '';
for (const item of items) {
  templateContent += (item.json.content || item.json.Content || Object.values(item.json).join(' ')) + '\n';
}
for (const [key, value] of Object.entries(variables)) {
  const placeholder = new RegExp(`\\{\\{${key}\\}\\}`, 'g');
  templateContent = templateContent.replace(placeholder, value);
}
const html = `<!DOCTYPE html><html><head><style>
  body { font-family: 'Times New Roman', serif; margin: 60px; line-height: 1.8; color: #333; }
  h1 { text-align: center; color: #2c3e50; border-bottom: 2px solid #333; padding-bottom: 10px; }
  .section { margin: 20px 0; }
  .signature-block { margin-top: 60px; display: flex; justify-content: space-between; }
  .sig-line { border-top: 1px solid #333; width: 200px; text-align: center; padding-top: 5px; }
  .footer { text-align: center; color: #999; font-size: 10px; margin-top: 40px; }
</style></head><body>
  <h1>${templateType}</h1>
  <div class="section">${templateContent.replace(/\n/g, '<br>')}</div>
  <div class="signature-block">
    <div><div class="sig-line">Party A: ${variables.partyA || '____________'}</div></div>
    <div><div class="sig-line">Party B: ${variables.partyB || '____________'}</div></div>
  </div>
  <div class="footer">Generated: ${new Date().toISOString()} | Document ID: ${templateType}-${Date.now()}</div>
</body></html>`;
return [{ json: { html, templateType, variables, documentId: `${templateType}-${Date.now()}`, generatedAt: new Date().toISOString() } }];

